    nums.sort()
    compressed = []
    start = nums[0]

    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1] + 1:
            continue
        else:
            if start != nums[i - 1]:
                compressed.append(f"{start}")
            else:
                compressed.append(str(start))
            if i < len(nums) - 1 and nums[i + 1] == nums[i] + 1:
                compressed.pop()  # Remove the last element to avoid adding a range
            compressed.append("-")
            compressed.append(str(nums[i]))
            start = nums[i]

    if start != nums[-1]:
        compressed.append(f"{start}")
    else:
        compressed.append(str(start))

    return ",".join(compressed)

